`ifdef RTL
    `define CYCLE_TIME 15
`endif

`ifdef GATE
    `define CYCLE_TIME 15
`endif


module PATTERN(
    // Output signals
	clk,
    rst_n,
    in_mode_valid,
    in_mode,
    in_data_valid,
    in_data,
    // Input signals
    out_valid,
    out_data,
    out_warn
);

//================================================================ 
//   INPUT AND OUTPUT DECLARATION
//================================================================
output reg clk, rst_n, in_mode_valid, in_mode, in_data_valid;
output reg signed [5:0] in_data;
input out_valid;
input signed [7:0] out_data;
input out_warn;

//================================================================
// parameters & integer
//================================================================
real CYCLE = `CYCLE_TIME;
parameter PATNUM = 200;  
integer patcount, total_latency, wait_val_time;
integer i, x, mode_value;
integer in_read, out_read, scan_status;
parameter OUT_NUM = 128;
parameter MAX_LATENCY = 100;

//================================================================
// wire & registers 
//================================================================
reg signed [7:0] golden_ans;
reg golden_warn;

//================================================================
// clock
//================================================================
initial 
begin
	clk = 0;
end
always #(CYCLE/2.0) clk = ~clk;

//================================================================
// initial
//================================================================
initial 
begin
	//+++++++++++++++++++++++++++++++++++++++++++++++++++
	in_read=$fopen("../00_TESTBED/input.txt","r");
  	out_read=$fopen("../00_TESTBED/output.txt","r");
	//+++++++++++++++++++++++++++++++++++++++++++++++++++

	rst_n = 1'b1;
	in_mode_valid = 1'b0;
	in_mode = 1'bx;
	in_data_valid = 1'b0;
	in_data = 'bx;
	force clk = 0;
 	total_latency = 0;
 	
	reset_signal_task;
	
	for(patcount = 1; patcount <= PATNUM; patcount = patcount + 1) 
	begin

        x = 0;

		input_task;
		wait_out_valid;
		check_ans;
	end	
  	YOU_PASS_task;
end 

always begin	
	if(out_valid === 1'b0 && (out_data !== 8'd0 || out_warn !== 1'b0))begin
        display_fail;
        $display ("---------------------------------------------------------------------------------------------");
        $display ("             Fail! Output signals should be 0 after your out_valid is pulled down.                   ");
        $display ("---------------------------------------------------------------------------------------------");
        repeat(2) #CYCLE;
        $finish;
    end
	else @(negedge clk);
end

// I/O_valid overlap
always begin	
	if(out_valid===1&&(in_mode_valid===1||in_data_valid===1))begin
        display_fail;
        $display ("---------------------------------------------------------------------------------------------");
        $display ("             Fail! The out_valid should not be high when input valid is high.                 ");
        $display ("---------------------------------------------------------------------------------------------");
        $finish;
	end
	else @(negedge clk);
end

//================================================================
// task
//================================================================
task reset_signal_task; 
begin 
    #(10);  rst_n=0;
    #(5);
    if((out_valid !== 1'b0)||(out_data !== 8'd0) || (out_warn !== 1'b0)) 
    begin
        display_fail;
        $display ("---------------------------------------------------------------------------------------------");
        $display ("             Fail! Output signals should be 0 after reset at %4t.", $time);
        $display ("---------------------------------------------------------------------------------------------");
        $finish;
    end
      
    #(50);  rst_n=1;
    #(3);  release clk;
end 
endtask

task input_task; 
begin
    if(patcount=='d1) repeat(2)@(negedge clk);

	// set mode
    scan_status = $fscanf(in_read, "%d", mode_value);
    in_mode_valid = 1'b1;
    in_mode = mode_value[0];
    @(negedge clk);
    in_mode_valid = 1'b0;
    in_mode = 1'bx;
    repeat($urandom_range(2, 4))@(negedge clk);

	// set in_data_valid and in_data
    in_data_valid = 1'b1;
    for(i = 0; i < 128; i = i + 1)
    begin
        scan_status = $fscanf(in_read, "%d", in_data);
        @(negedge clk);
    end
    
	// Disable input
    in_data_valid = 1'b0;
    in_data = 'bx;        
end
endtask

task wait_out_valid; 
begin
    wait_val_time = 0;
    while(out_valid !== 1) begin
        wait_val_time = wait_val_time + 1;
        if(wait_val_time > MAX_LATENCY)
        begin
            display_fail;
            $display ("---------------------------------------------------------------------------------------------");
            $display ("             Fail! The execution latency is over %d cycles.", MAX_LATENCY);
            $display ("---------------------------------------------------------------------------------------------");
            repeat(2)@(negedge clk);
            $finish;
        end
        @(negedge clk);
    end

    total_latency = total_latency + wait_val_time;
end endtask

task check_ans; 
begin
    scan_status = $fscanf(out_read, "%d", golden_warn);

    while(out_valid === 1) begin
        if(x >= OUT_NUM) begin
            display_fail;
            $display ("---------------------------------------------------------------------------------------------");
            $display ("             Fail! OUT_VALID is over %d cycle(s)", OUT_NUM);
            $display ("---------------------------------------------------------------------------------------------");
            repeat(9) @(negedge clk);
            $finish;
        end

        scan_status = $fscanf(out_read, "%d", golden_ans);

        if (out_warn !== golden_warn) begin
            display_fail;
            $display ("---------------------------------------------------------------------------------------------");
            $display ("             Fail! OUT_WARN is wrong!");
            $display ("             PATTERN NO.%4d", patcount);
            $display ("             Ans:%d", golden_warn);
            $display ("             Your output:%d at %8t", out_warn, $time);
            $display ("---------------------------------------------------------------------------------------------");
            repeat(9) @(negedge clk);
            $finish;
        end

        if(out_data !== golden_ans) begin
            display_fail;
            $display ("---------------------------------------------------------------------------------------------");
            $display ("             Fail! VN POST LLR IS WRONG!");
            $display ("             PATTERN NO.%4d . VN %4d", patcount, x);
            $display ("             Ans:%d", golden_ans);
            $display ("             Your output:%d at %8t", out_data, $time);
            $display ("---------------------------------------------------------------------------------------------");
            repeat(9) @(negedge clk);
            $finish;
        end

        x = x + 1;
        @(negedge clk);
    end

    if (out_valid !== 1'b0) begin
        display_fail;
        $display("Fail! out_valid must return to 0.");
        $finish;
    end

    if(x < OUT_NUM) begin
        display_fail;
        $display ("---------------------------------------------------------------------------------------------");
        $display ("                   Fail! OUT_VALID is less than %d cycle(s)", OUT_NUM);
        $display ("---------------------------------------------------------------------------------------------");
        repeat(3) @(negedge clk);
        $finish;
    end

    $display("\033[0;34mPASS PATTERN NO.%4d,\033[m \033[0;32mexecution latency : %3d\033[m", patcount, wait_val_time);
    repeat($urandom_range(2, 4))@(negedge clk);
end 
endtask

task YOU_PASS_task; 
begin
	display_pass;
    $display ("--------------------------------------------------------------------------------------------------");        
    $display ("                                          Congratulations!!!                         ");
    $display ("                                   You have passed all patterns!                     ");
    $display ("                                   Total lentency : %d cycles                     ", total_latency);
    $display ("--------------------------------------------------------------------------------------------------"); 


    #(500);
    $finish;
end
endtask

